const Glyph& glyph(QChar c){for(const auto& g:glyphs)if(c.unicode()==unsigned(g.character))return g;throw std::runtime_error("tom-handwriting-unsupported-character");}
double jitter(unsigned seed,unsigned at,unsigned channel){std::uint32_t v=seed^(at*2654435761u)^(channel*2246822519u);v^=v>>15;v*=3266489917u;v^=v>>16;return double(v%2001)/1000-1;}
QString normalize(QString s){s.replace(QChar(0x2018),QChar('\''));s.replace(QChar(0x2019),QChar('\''));s.replace(QChar(0x201c),QChar('"'));s.replace(QChar(0x201d),QChar('"'));s.replace(QChar(0x2013),QChar('-'));s.replace(QChar(0x2014),QStringLiteral(" -- "));s.replace(QChar(0x2026),QStringLiteral("..."));s.replace(QChar(0xa0),QChar(' '));s.replace(QChar(0x2022),QChar('*'));s.replace(QChar(0x2192),QStringLiteral(" -> "));s.replace(QChar(0x2190),QStringLiteral(" <- "));return s.normalized(QString::NormalizationForm_D);}
