nativeink::Group handwriting(const QString& original,const HandwritingOptions& o,const std::atomic<bool>* stop){product::require(!original.trimmed().isEmpty()&&original.size()<=16000&&!original.contains(QChar(0)),"tom-handwriting-text-capacity");product::require(std::isfinite(o.size)&&o.size>=16&&o.size<=80&&o.x>=4&&o.y>=4&&o.width>=120&&o.x+o.width<=1476&&o.height>=100&&o.y+o.height<=16996,"tom-handwriting-layout-bounds");product::validateStyle(o.style);QJsonArray strokes;std::vector<nativeink::StrokeTiming> timing;auto boundary=[&](unsigned pause){timing.resize(strokes.size());if(!timing.empty())timing.back().pauseAfterMs=std::max(timing.back().pauseAfterMs,pause);};unsigned at=0;double y=o.y;auto text=normalize(original);for(auto line:text.split('\n')){nativeink::checkCancelled(stop);bool heading=QRegularExpression("^#{1,6}\\s+").match(line).hasMatch();if(heading){while(line.startsWith('#'))line.remove(0,1);line=line.trimmed();}double size=o.size*(heading?1.18:1),scale=size/10,lineHeight=size*1.65,x=o.x,indent=o.x,accentX=o.x,accentTop=o.y;bool list=QRegularExpression("^\\s*(?:[-*] |[0-9]+[.)] )").match(line).hasMatch();if(list)indent+=size*1.2;if(line.isEmpty()){boundary(300);y+=lineHeight*.65;continue;}
 auto width=[&](const QString& word){double n=0;for(auto c:word){if(c.category()==QChar::Mark_NonSpacing)continue;n+=(glyph(c).advance+1.0)*scale;}return n;};
 for(const auto& word:line.split(QRegularExpression("\\s+"),Qt::SkipEmptyParts)){if(x>indent&&x+width(word)+size*.18>o.x+o.width){boundary(110);x=indent;y+=lineHeight;}for(auto c:word){nativeink::checkCancelled(stop);if(c.category()==QChar::Mark_NonSpacing){product::require(c.unicode()==0x301||c.unicode()==0x300||c.unicode()==0x302||c.unicode()==0x308||c.unicode()==0x303||c.unicode()==0x327,"tom-handwriting-unsupported-accent");double w=size*.22,top=accentTop-size*.12;QJsonArray p;if(c.unicode()==0x327)p={QJsonArray{accentX,y+size*1.10},QJsonArray{accentX+w*.3,y+size*1.22},QJsonArray{accentX-w*.3,y+size*1.30}};else if(c.unicode()==0x308){strokes.append(QJsonObject{{"style",o.style},{"points",QJsonArray{QJsonArray{accentX-w*.45,top},QJsonArray{accentX-w*.45+.1,top}}}});p={QJsonArray{accentX+w*.45,top},QJsonArray{accentX+w*.45+.1,top}};}else if(c.unicode()==0x302)p={QJsonArray{accentX-w*.5,top},QJsonArray{accentX,top-w*.6},QJsonArray{accentX+w*.5,top}};else if(c.unicode()==0x303)p={QJsonArray{accentX-w*.6,top},QJsonArray{accentX-w*.2,top-w*.35},QJsonArray{accentX+w*.2,top},QJsonArray{accentX+w*.6,top-w*.35}};else if(c.unicode()==0x300)p={QJsonArray{accentX-w*.4,top-w*.6},QJsonArray{accentX+w*.4,top}};else p={QJsonArray{accentX-w*.4,top},QJsonArray{accentX+w*.4,top-w*.6}};strokes.append(QJsonObject{{"style",o.style},{"points",p}});continue;}const auto& g=glyph(c);double advance=(g.advance+1)*scale;if(x+advance+size*.18>o.x+o.width){boundary(110);x=indent;y+=lineHeight;}product::require(y+size*1.5<=o.y+o.height,"tom-handwriting-area-full");accentX=x+g.advance*scale*.5;accentTop=y+(c.isLower()?size*.4:0);double vary=1+jitter(o.seed,at,0)*.025,baseline=jitter(o.seed,at,1)*scale*.18,slant=.10+jitter(o.seed,at,2)*.015;for(const auto& path:QString::fromLatin1(g.paths).split(';')){QJsonArray points;for(const auto& token:path.split(' ',Qt::SkipEmptyParts)){auto xy=token.split(',');double px=xy[0].toDouble(),py=xy[1].toDouble();points.append(QJsonArray{x+(px+slant*(10-py))*scale*vary,y+py*scale*vary+baseline});}if(QStringLiteral("abcedgoqsuBCDGOQRSU").contains(c)&&points.size()>2){QJsonArray smooth;auto atPoint=[&](int i){return points[std::clamp(i,0,int(points.size())-1)].toArray();};smooth.append(points.first());for(int n=0;n+1<points.size();++n){auto a=atPoint(n-1),b=atPoint(n),d=atPoint(n+1),e=atPoint(n+2);for(int k=1;k<=4;++k){double t=double(k)/4;auto coord=[&](int axis){double p0=a[axis].toDouble(),p1=b[axis].toDouble(),p2=d[axis].toDouble(),p3=e[axis].toDouble();return .5*(2*p1+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t*t+(-p0+3*p1-3*p2+p3)*t*t*t);};smooth.append(QJsonArray{coord(0),coord(1)});}}points=smooth;}strokes.append(QJsonObject{{"style",o.style},{"points",points}});product::require(strokes.size()<=int(nativeink::MaxStrokes),"tom-handwriting-stroke-capacity");}x+=advance*(1+jitter(o.seed,at,3)*.025);++at;}boundary(QStringLiteral(".!?").contains(word.back())?180:QStringLiteral(",;:").contains(word.back())?100:35);x+=size*(.32+jitter(o.seed,at,4)*.015);}boundary(heading?240:110);y+=lineHeight*(heading?1.1:1);}
 auto result=nativeink::checked(strokes,"tom_handwriting");timing.resize(strokes.size());for(int i=0;i<strokes.size();++i)timing[std::size_t(i)].complexity=1+.012*std::min(32,int(strokes[i].toObject()["points"].toArray().size()));result.timing=std::move(timing);return result;}
